import sys,random,copy,json,time
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/tmp')
import engine,ref_engine
rng=random.Random(31415)
def rb(ro):
 U=rng.randint(1,200)
 cuts=sorted(rng.sample(range(1,U),min(ro-1,U-1)))
 return [0]+cuts+[U]
for case in range(200):
 M=rng.randint(1,8);L=rng.randint(1,4);R=rng.randint(1,12);kind=rng.choice(['fifo','sp','sff','wfq'])
 flows=list(range(rng.randint(2,15)))
 spec={'kind':kind}
 if kind=='sp': spec['levels']=[[f,rng.randint(0,100)] for f in flows]
 if kind=='wfq': spec['weights']=[[f,rng.randint(1,20)] for f in flows]
 run={'banks':M,'load_balancers':L,'fifo_bytes':rng.randint(1,200),'pifo_bytes':rng.randint(1,150),'refill_batch':rng.randint(1,10),'sample_period':rng.randint(1,15),'borders':rb(R),'policy':spec,'events':[]}
 ev=run['events'];nid=1;saves=[]
 for j in range(rng.randint(100,300)):
  c=rng.choice(['enqueue']*3+['dequeue']*2+['sample','repartition','cancel','inspect','weight','save']+(['restore']*3 if saves else []))
  if c=='enqueue': ev.append(['enqueue',nid,rng.choice(flows),rng.randint(1,40),rng.randint(0,150)]);nid+=1
  elif c=='dequeue': ev.append(['dequeue',rng.randint(1,5)])
  elif c=='sample': ev.append(['sample'])
  elif c=='repartition': ev.append(['repartition',rb(rng.randint(1,12))])
  elif c=='cancel': ev.append(['cancel',rng.randint(0,nid+2)])
  elif c=='inspect': ev.append(['inspect',rng.randint(0,nid+2)])
  elif c=='weight':
   if kind=='wfq': ev.append(['weight',rng.choice(flows),rng.randint(1,20)])
   else: ev.append(['inspect',rng.randint(0,nid+2)])
  elif c=='save': name=rng.randrange(10);ev.append(['save',name]);saves.append(name)
  else: ev.append(['restore',rng.choice(saves)])
 req={'runs':[run]}
 a=engine.run_request(copy.deepcopy(req));b=ref_engine.run_request(copy.deepcopy(req))
 if a!=b:
  print('mismatch',case);json.dump(req,open('/tmp/fuzzbigbad.json','w'))
  la=a['runs'][0]['log'];lb=b['runs'][0]['log']
  for i,(x,y) in enumerate(zip(la,lb)):
   if x!=y: print('log',i,x,y);break
  if a['runs'][0]['state']!=b['runs'][0]['state']: print('state diff')
  break
else: print('big fuzz ok')
